#!/usr/bin/env node
/**
 * calendar-extractor — generated by JavisSkills/skill-creator (improved build)
 * AUTO-RUN by the javis-server session-dispatcher when a completed unit matches the
 * `calendar` route (no approve-to-run card — the dispatcher passes a deliverable
 * HINT in the run prompt that the agent may use alongside the transcript), OR run
 * by the LLM on user-typed commands ("today's meetings" / "calendar extract").
 *
 * Two subcommands:
 *   fetch  GET recent session transcripts from javis-server and print them as JSON
 *          to stdout. The agent reads this and extracts the calendar events.
 *          With --session <id> / --kbd-input <id> the payload is filtered to a
 *          single unit (the auto-run dispatcher unit); with no flags it returns the
 *          whole time window (the manual ask), unchanged.
 *   push   read an extracted-events JSON array on stdin, dedup it against per-user
 *          local state (the `seen` map), mirror it to the server skill_data store
 *          tagged status:"pending" (best-effort), and push a markdown digest of the
 *          NEW events to the user's iOS chat. The skill does NOT self-gate per unit —
 *          the server owns run-once (DispatchRouteExecuted); the human gate is the
 *          Confirm/Discard on the PENDING calendar rows, not an approve-to-run card.
 *
 * Usage:
 *   node calendar-extractor.js <userId> fetch [--hours N] [--limit N]
 *   node calendar-extractor.js <userId> fetch --session <sessionId> [--hours N]
 *   node calendar-extractor.js <userId> fetch --kbd-input <inputId> [--hours N]
 *   node calendar-extractor.js <userId> push  < events.json
 *   node calendar-extractor.js --help
 *
 * Env:
 *   OPENCLAW_GATEWAY_TOKEN  required for fetch/push — Bearer auth to javis-server
 *                           (injected automatically inside the openclaw container)
 *   JAVIS_SERVER_URL        optional — defaults to http://javis-server:8000
 *   TZ                      optional — IANA zone used when the fetch payload carries
 *                           no tz; otherwise the system zone is used.
 *
 * Verified endpoints (javis-server):
 *   GET  /api/transcripts/recent  (get_gateway_user; params since, limit)
 *   GET  /api/transcripts/keyboard-input/<id>  (get_gateway_user; one keyboard row)
 *   POST /api/agent/push          (get_gateway_user; {skill, content, session_id?})
 *   POST /api/skill/data          (get_gateway_user; upsert by dedup_key)
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { resolveUserId, safeUserPath, readJson, writeJson } = require('./data');
const {
  isoOrNull,
  normalizeEvent,
  dedupKey,
  localAnchor,
  buildSkillDataItems,
  pruneSeen,
} = require('./lib');

const SLUG = 'calendar-extractor';
const SERVER = process.env.JAVIS_SERVER_URL || 'http://javis-server:8000';

// argv is parsed lazily so `require()`-ing this module from a unit test is
// side-effect-free (no --help exit, no userId sanitize/exit on the test runner's
// argv). The CLI entry point (main) is the only caller of parseArgv().
const SUBCOMMANDS = ['fetch', 'push'];
let userId, subcommand, rest;

function parseArgv() {
  if (process.argv.includes('--help')) {
    console.log([
      'Usage:',
      '  node calendar-extractor.js <userId> fetch [--hours N] [--limit N]',
      '  node calendar-extractor.js <userId> fetch --session <sessionId> [--hours N]',
      '  node calendar-extractor.js <userId> fetch --kbd-input <inputId> [--hours N]',
      '  node calendar-extractor.js <userId> push  < events.json',
      '',
      'fetch  GET recent transcripts from javis-server -> JSON on stdout',
      '         --session/--kbd-input filter to one unit (the auto-run dispatcher unit)',
      'push   read extracted-events JSON on stdin -> dedup (seen) + push markdown digest to iOS',
    ].join('\n'));
    process.exit(0);
  }

  // userId is optional. Positional parsing must not mistake a bare subcommand
  // (e.g. `calendar-extractor.js fetch`) for the userId.
  const a2 = process.argv[2];
  if (SUBCOMMANDS.includes(a2)) {
    // userId omitted — argv[2] is the subcommand (zero-config interactive use)
    userId = resolveUserId(null);
    subcommand = a2;
    rest = process.argv.slice(3);
  } else {
    // explicit userId provided (back-compat, multi-profile)
    userId = resolveUserId(a2);
    subcommand = process.argv[3] || 'fetch';
    rest = process.argv.slice(4);
  }
}

function getFlag(name, dflt) {
  const i = rest.indexOf(`--${name}`);
  return i >= 0 && i + 1 < rest.length ? rest[i + 1] : dflt;
}

function requireToken() {
  const t = process.env.OPENCLAW_GATEWAY_TOKEN;
  if (!t) throw new Error('OPENCLAW_GATEWAY_TOKEN is required (injected inside the openclaw container).');
  return t;
}

function loadState() {
  const p = safeUserPath(userId);
  if (!fs.existsSync(p)) return { userId };
  try {
    return readJson(p);
  } catch (e) {
    // A truncated/corrupt state file (e.g. a kill mid-write before the atomic
    // rename landed, on an older volume) must not brick every future run.
    // `seen` is best-effort dedup state, so start fresh.
    console.error(`⚠️ state file unreadable, starting fresh: ${e.message}`);
    return { userId };
  }
}
function saveState(state) {
  writeJson(safeUserPath(userId), state);
}

// tz resolution order: tz from the fetch payload -> TZ env var -> system zone.
// tz comes from payload/env/system; no per-user prefs lookup.
function resolveTz(payloadTz) {
  if (payloadTz && typeof payloadTz === 'string' && payloadTz.trim()) return payloadTz.trim();
  if (process.env.TZ && process.env.TZ.trim()) return process.env.TZ.trim();
  try {
    const z = Intl.DateTimeFormat().resolvedOptions().timeZone;
    if (z) return z;
  } catch (_) { /* fall through */ }
  return 'UTC';
}

// ---- fetch ---------------------------------------------------------------
// Pull the source field off a session payload, normalizing the two server
// shapes (`source` is the documented field; `source_kind` is tolerated).
function sessionSource(s) {
  return (s && (s.source || s.source_kind) || '').toString().trim().toLowerCase();
}
function sessionId(s) {
  return (s && (s.session_id || s.id) || '').toString().trim();
}

// Apply the single-unit filter shared by the CLI and tests. `--session` (audio)
// keeps the one non-keyboard session whose session_id matches; `--kbd-input`
// (keyboard) resolves a single row via the dedicated server endpoint.
//
// `--kbd-input <id>` resolves one keyboard row via
// GET /api/transcripts/keyboard-input/<id> (which returns that row as a one-entry
// payload with session_id=str(input id), source="keyboard"); `/api/transcripts/recent`
// aggregates keyboard rows by daily session_id and carries no per-row id, so it can
// only serve the audio `--session` filter and the manual time-window path.
//
// Returns the filtered sessions array; `--session` (audio) keeps the one non-keyboard
// session whose session_id matches. With no filter the input is unchanged.
function filterToUnit(sessions, { sessionFilter }) {
  if (sessionFilter) {
    return sessions.filter((s) => sessionSource(s) !== 'keyboard' && sessionId(s) === sessionFilter);
  }
  return sessions;
}

// IO-injectable core so doFetch is unit-testable. `deps.httpGet(url, token)`
// returns the parsed JSON body (the default hits javis-server via fetch).
async function doFetch(opts = {}, deps = {}) {
  const token = opts.token || requireToken();
  const httpGet = deps.httpGet || defaultHttpGet;
  const nowIso = deps.now ? deps.now() : new Date().toISOString();

  // --session (audio) / --kbd-input (keyboard) target one unit for the auto-run
  // dispatcher unit; a unit outside the default window widens --hours as needed.
  // Tests inject opts.* directly; the CLI leaves them undefined and we read argv.
  const sessionFilter = 'sessionFilter' in opts ? opts.sessionFilter : getFlag('session', null);
  const kbdFilter = 'kbdFilter' in opts ? opts.kbdFilter : getFlag('kbd-input', null);
  const hours = 'hours' in opts ? opts.hours : (parseInt(getFlag('hours', '24'), 10) || 24);
  const limit = 'limit' in opts ? opts.limit : (parseInt(getFlag('limit', '50'), 10) || 50);

  // --kbd-input resolves one keyboard row via the dedicated per-input endpoint
  // (the aggregated /transcripts/recent carries no keyboard_input.id). It already
  // returns exactly that unit, so no client-side filter is applied.
  const url = kbdFilter
    ? `${SERVER}/api/transcripts/keyboard-input/${encodeURIComponent(kbdFilter)}`
    : `${SERVER}/api/transcripts/recent?since=${encodeURIComponent(new Date(Date.now() - hours * 3600 * 1000).toISOString())}&limit=${limit}`;
  const data = await httpGet(url, token);

  // Normalize to a sessions array regardless of the server envelope shape.
  const isEnvelope = data && typeof data === 'object' && !Array.isArray(data);
  let sessions = isEnvelope
    ? (Array.isArray(data.sessions) ? data.sessions : [])
    : (Array.isArray(data) ? data : []);

  // --session (audio) filters the recent window; --kbd-input is already one unit.
  if (!kbdFilter) sessions = filterToUnit(sessions, { sessionFilter });

  // tz order: payload tz (test override / server envelope) -> TZ env -> system.
  const base = isEnvelope ? data : {};
  const payloadTz = 'tz' in opts ? opts.tz : (deps.tz != null ? deps.tz : base.tz);
  const tz = resolveTz(payloadTz);

  // Anchor for relative-date resolution: the agent MUST resolve "tomorrow/Saturday/
  // next Thursday/around 6,7,8" against the anchor — never its own notion of "today".
  // The anchor is LOCAL wall-clock in tz (not the raw UTC instant): a Z instant's
  // date can already be the next day in the evening west of UTC, which made the LLM
  // resolve "today" one day late. localAnchor() hands it reference_time (zoneless
  // local), reference_date, reference_weekday, and reference_time_utc (true instant).
  const out = { ...localAnchor(nowIso, tz), tz, ...base, sessions };
  if (deps.emit) deps.emit(out);
  else console.log(JSON.stringify(out, null, 2));
  return out;
}

async function defaultHttpGet(url, token) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error(`GET ${url.replace(SERVER, '')} -> HTTP ${res.status}`);
  return res.json();
}

// ---- push helpers --------------------------------------------------------
function formatDigest(events, tz) {
  const lines = ['## 📅 Calendar — new meetings / 新会议', ''];
  for (const ev of events) {
    let when = ev.startAt
      ? new Date(ev.startAt).toLocaleString('en-US', { timeZone: tz })
      : 'time TBD';
    if (ev.startAt && ev.endAt) {
      when += ` – ${new Date(ev.endAt).toLocaleTimeString('en-US', { timeZone: tz })}`;
    }
    lines.push(`- **${ev.title}**`);
    lines.push(`  - 🕘 ${when}`);
    if (ev.location) lines.push(`  - 📍 ${ev.location}`);
    if (ev.attendees.length) lines.push(`  - 👥 ${ev.attendees.join(', ')}`);
    if (ev.notes) lines.push(`  - 📝 ${ev.notes}`);
  }
  return lines.join('\n');
}

// Per-card markdown for ONE event — the section heading plus that event's
// details, reusing formatDigest's per-event formatting. Each card is pushed on
// its own /api/agent/push (with the event's dedup_key) so the server routes it
// into that card's own Agent Chat session (derive_card_session_id), giving every
// calendar event its own iOS chat thread instead of one combined digest.
function formatCardPush(ev, tz) {
  const lines = ['## 📅 Calendar — new meeting / 新会议', ''];
  let when = ev.startAt
    ? new Date(ev.startAt).toLocaleString('en-US', { timeZone: tz })
    : 'time TBD';
  if (ev.startAt && ev.endAt) {
    when += ` – ${new Date(ev.endAt).toLocaleTimeString('en-US', { timeZone: tz })}`;
  }
  lines.push(`- **${ev.title}**`);
  lines.push(`  - 🕘 ${when}`);
  if (ev.location) lines.push(`  - 📍 ${ev.location}`);
  if (ev.attendees.length) lines.push(`  - 👥 ${ev.attendees.join(', ')}`);
  if (ev.notes) lines.push(`  - 📝 ${ev.notes}`);
  return lines.join('\n');
}

async function pushToiOS(token, content, dedupKey) {
  // dedup_key is included ONLY when provided: a no-key call must stay
  // byte-identical to the legacy aggregate body. When present, the server routes
  // the push into the card's own Agent Chat session (no explicit session_id).
  const body = { skill: SLUG, content };
  if (dedupKey) body.dedup_key = dedupKey;
  const res = await fetch(`${SERVER}/api/agent/push`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`POST /api/agent/push -> HTTP ${res.status}`);
}

async function mirrorToSkillData(token, events, tz) {
  // Best-effort server-side mirror so the iOS app can read events via Clerk auth.
  // The container's gateway token can WRITE here, but cannot read back
  // (GET /api/skill/data requires a Clerk JWT) — so local state is the dedup
  // source of truth and this mirror is non-fatal.
  //
  // start_at/end_at MUST be naive LOCAL wall-clock in `tz`, not a UTC instant:
  // iOS (Sources/JavisApp/utils/ServerDate.swift) reads calendar datetimes as
  // zoneless local time, so a `Z` instant would shift by the tz offset.
  //
  // Every item is tagged status:"pending" (Flow 3): the server stores the event
  // pending and the iOS calendar table shows it greyed/dashed with Confirm/Discard.
  // The event becomes solid only when the user taps Confirm; Discard deletes it.
  const items = buildSkillDataItems(events, tz);
  const res = await fetch(`${SERVER}/api/skill/data`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ skill: SLUG, type: 'event', merge: 'upsert', items }),
  });
  if (!res.ok) throw new Error(`POST /api/skill/data -> HTTP ${res.status}`);
}

// The two server writes the push path performs, wrapped so tests can inject a
// recording mock instead of the real javis-server client. Each method takes the
// normalized events so a test can assert exactly which events hit the table.
const defaultPushClient = {
  mirror: (token, events, tz) => mirrorToSkillData(token, events, tz),
  push: (token, content, dedupKey) => pushToiOS(token, content, dedupKey),
};

// Read + parse + normalize the stdin events array.
async function readStdinEvents() {
  let input = '';
  for await (const chunk of process.stdin) input += chunk;
  input = input.trim();
  if (!input) throw new Error("push expects a JSON array of events on stdin (got empty input).");

  let parsed;
  try { parsed = JSON.parse(input); }
  catch (e) { throw new Error(`stdin is not valid JSON: ${e.message}`); }

  const rawEvents = Array.isArray(parsed)
    ? parsed
    : (Array.isArray(parsed.events) ? parsed.events : []);
  return rawEvents.map(normalizeEvent).filter(Boolean);
}

// ---- push ----------------------------------------------------------------
// The skill does NOT self-gate per unit: the server owns run-once
// (DispatchRouteExecuted), and the human gate is Confirm/Discard on the PENDING
// calendar rows (not an approve-to-run card). push only dedups individual events
// against the `seen` map so the same event is never delivered twice across
// overlapping manual 24h windows or a re-run.
async function doPush(deps = {}) {
  const client = deps.client || defaultPushClient;
  const load = deps.load || loadState;
  const save = deps.save || saveState;
  const tz = deps.tz || resolveTz(null);
  const token = deps.token || requireToken();
  const events = deps.events || await readStdinEvents();

  const state = load();
  const seen = pruneSeen(state.seen || {});
  const nowIso = deps.now ? deps.now() : new Date().toISOString();

  // Event-level dedup: only events not already delivered are new.
  const fresh = [];
  for (const ev of events) {
    const key = dedupKey(ev);
    if (!seen[key]) fresh.push({ ev, key });
  }

  if (!fresh.length) {
    state.seen = seen;
    state.lastRunAt = nowIso;
    save(state);
    console.log('No new events to push.');
    return;
  }

  const freshEvents = fresh.map((f) => f.ev);

  try { await client.mirror(token, freshEvents, tz); }
  catch (e) { console.error('⚠️ skill_data mirror failed (non-fatal):', e.message); }

  // One push per fresh event, each carrying that event's dedup_key (key ===
  // dedupKey(ev), the same string written to its skill_data row). The server
  // routes each into the card's own Agent Chat session, so every calendar event
  // lands in its own iOS thread — replacing the single aggregate digest.
  for (const f of fresh) {
    await client.push(token, formatCardPush(f.ev, tz), f.key);
  }

  for (const f of fresh) seen[f.key] = nowIso;
  state.seen = seen;
  state.lastRunAt = nowIso;
  save(state);
  console.log(`Pushed ${freshEvents.length} new event(s) to iOS.`);
}

async function main() {
  parseArgv();
  if (subcommand === 'fetch') return doFetch();
  if (subcommand === 'push') return doPush();
  throw new Error(`Unknown subcommand '${subcommand}'. Use 'fetch' or 'push' (see --help).`);
}

// Export the load-bearing functions for unit tests (with injected IO). When run
// as a CLI (`node calendar-extractor.js …`) require.main is this module, so the
// entry point fires; under `require()` from a test it stays dormant.
module.exports = {
  doFetch,
  doPush,
  resolveTz,
  filterToUnit,
  sessionSource,
  sessionId,
  formatDigest,
  formatCardPush,
};

if (require.main === module) {
  main().catch((err) => {
    console.error('❌', err.message);
    process.exit(1);
  });
}
